/* Standard E-Commerce Product Layout */
.standard-product-layout {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: #090a0f;
  color: #e5e7eb;
  min-height: 80vh;
}
.standard-product-layout .layout-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}
.standard-product-layout .product-breadcrumb-wrap {
  padding-top: 2rem;
  padding-bottom: 0.75rem;
}
.standard-product-layout .breadcrumb-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 0.85rem;
  color: #9ca3af;
}
.standard-product-layout .breadcrumb-list a {
  color: #cbd5e1;
  text-decoration: none;
  transition: color 0.15s ease;
}
.standard-product-layout .breadcrumb-list a:hover {
  color: #ff5e3a;
}
.standard-product-layout .breadcrumb-current {
  color: #ffffff;
  font-weight: 600;
}
.standard-product-layout .product-main-section {
  padding: 1.5rem 0 3.5rem;
}
.standard-product-layout .product-showcase-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  gap: 3rem;
  align-items: start;
}
@media (max-width: 900px) {
  .standard-product-layout .product-showcase-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}
.standard-product-layout .main-image-viewport {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  background: #11141c;
  border: 1px solid #1e2533;
  aspect-ratio: 4 / 5;
}
.standard-product-layout .main-image-viewport img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: opacity 0.2s ease, transform 0.35s ease;
}
.standard-product-layout .gallery-badges-overlay {
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  pointer-events: none;
}
.standard-product-layout .badge-discount-tag {
  background: #ef4444;
  color: #fff;
  font-size: 0.72rem;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 6px;
  letter-spacing: 0.04em;
}
.standard-product-layout .badge-stock-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(15, 19, 29, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(16, 185, 129, 0.35);
  color: #6ee7b7;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 9999px;
}
.standard-product-layout .badge-stock-pill.out-of-stock {
  border-color: rgba(239, 68, 68, 0.4);
  color: #fca5a5;
}
.standard-product-layout .badge-stock-pill.preorder {
  border-color: rgba(245, 158, 11, 0.4);
  color: #fcd34d;
}
.standard-product-layout .stock-pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.standard-product-layout .gallery-thumbs-reel {
  display: flex;
  gap: 10px;
  margin-top: 12px;
  flex-wrap: wrap;
}
.standard-product-layout .gallery-thumb-btn {
  width: 74px;
  height: 88px;
  border-radius: 10px;
  overflow: hidden;
  padding: 0;
  background: #11141c;
  border: 2px solid #1e2533;
  cursor: pointer;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.standard-product-layout .gallery-thumb-btn.active,
.standard-product-layout .gallery-thumb-btn:hover {
  border-color: #ff5e3a;
  transform: translateY(-2px);
}
.standard-product-layout .gallery-thumb-btn img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.standard-product-layout .info-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 12px;
}
.standard-product-layout .product-category-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 9999px;
  background: rgba(255, 94, 58, 0.14);
  color: #ff7b5a;
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-decoration: none;
}
.standard-product-layout .sku-text {
  font-size: 0.78rem;
  color: #94a3b8;
}
.standard-product-layout .single-product-title {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(1.75rem, 2.6vw, 2.4rem);
  font-weight: 800;
  color: #ffffff;
  line-height: 1.2;
  margin: 0 0 8px 0;
}
.standard-product-layout .single-product-subtitle {
  font-size: 0.98rem;
  color: #94a3b8;
  line-height: 1.5;
  margin: 0 0 14px 0;
}
.standard-product-layout .rating-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: #cbd5e1;
  margin-bottom: 18px;
}
.standard-product-layout .stars-gold {
  color: #fbbf24;
  letter-spacing: 2px;
}
.standard-product-layout .pricing-card {
  background: #11141c;
  border: 1px solid #1f2633;
  border-radius: 12px;
  padding: 16px 18px;
  margin-bottom: 20px;
}
.standard-product-layout .price-display {
  display: flex;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
}
.standard-product-layout .main-price {
  font-size: 2rem;
  font-weight: 800;
  color: #ffffff;
}
.standard-product-layout .strike-price {
  font-size: 1.05rem;
  color: #64748b;
  text-decoration: line-through;
}
.standard-product-layout .savings-callout {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
  color: #34d399;
  font-size: 0.82rem;
}
.standard-product-layout .variant-group {
  margin-bottom: 18px;
}
.standard-product-layout .variant-label-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  font-size: 0.85rem;
}
.standard-product-layout .variant-label {
  color: #94a3b8;
}
.standard-product-layout .variant-selected-value {
  color: #ffffff;
}
.standard-product-layout .color-swatches-list {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.standard-product-layout .color-swatch-item {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid #2b3446;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.75rem;
  font-weight: 800;
  transition: transform 0.15s ease, border-color 0.15s ease;
}
.standard-product-layout .color-swatch-item .swatch-check {
  opacity: 0;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}
.standard-product-layout .color-swatch-item.selected {
  border-color: #ff5e3a;
  transform: scale(1.08);
  box-shadow: 0 0 0 2px rgba(255, 94, 58, 0.35);
}
.standard-product-layout .color-swatch-item.selected .swatch-check {
  opacity: 1;
}
.standard-product-layout .size-chips-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.standard-product-layout .size-chip-btn {
  min-width: 48px;
  padding: 8px 14px;
  background: #11141c;
  color: #cbd5e1;
  border: 1px solid #232b3a;
  border-radius: 8px;
  font-weight: 700;
  font-size: 0.84rem;
  cursor: pointer;
  transition: all 0.15s ease;
}
.standard-product-layout .size-chip-btn.selected,
.standard-product-layout .size-chip-btn:hover {
  border-color: #ff5e3a;
  color: #ffffff;
}
.standard-product-layout .size-chip-btn.selected {
  background: #ff5e3a;
}
.standard-product-layout .quantity-row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
}
.standard-product-layout .qty-stepper {
  display: inline-flex;
  align-items: center;
  border: 1px solid #232b3a;
  border-radius: 8px;
  background: #11141c;
  overflow: hidden;
}
.standard-product-layout .btn-qty {
  width: 36px;
  height: 36px;
  border: none;
  background: transparent;
  color: #e5e7eb;
  font-size: 1.1rem;
  cursor: pointer;
}
.standard-product-layout .btn-qty:hover {
  background: #1b2232;
}
.standard-product-layout .qty-number {
  width: 46px;
  text-align: center;
  background: transparent;
  border: none;
  color: #ffffff;
  font-weight: 700;
  font-size: 0.92rem;
}
.standard-product-layout .buy-action-box {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 22px;
}
.standard-product-layout .btn-primary-buy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 14px 22px;
  background: #ff5e3a;
  color: #ffffff;
  font-weight: 700;
  font-size: 1rem;
  border-radius: 10px;
  text-decoration: none;
  box-shadow: 0 8px 24px rgba(255, 94, 58, 0.3);
  transition: transform 0.15s ease, filter 0.15s ease;
}
.standard-product-layout .btn-primary-buy:hover {
  transform: translateY(-1px);
  filter: brightness(1.06);
}
.standard-product-layout .btn-secondary-inquire {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 12px 18px;
  background: #11141c;
  color: #e5e7eb;
  border: 1px solid #262f40;
  font-weight: 600;
  font-size: 0.9rem;
  border-radius: 10px;
  text-decoration: none;
  transition: border-color 0.15s ease, color 0.15s ease;
}
.standard-product-layout .btn-secondary-inquire:hover {
  border-color: #ff5e3a;
  color: #ffffff;
}
.standard-product-layout .trust-features-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding-top: 16px;
  border-top: 1px solid #1e2533;
}
.standard-product-layout .trust-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.8rem;
  color: #94a3b8;
}
.standard-product-layout .trust-item strong {
  display: block;
  color: #f3f4f6;
  font-size: 0.83rem;
}
.standard-product-layout .product-details-section {
  background: #0d1018;
  border-top: 1px solid #1e2533;
  border-bottom: 1px solid #1e2533;
  padding: 3rem 0;
}
.standard-product-layout .tabs-nav-bar {
  display: flex;
  gap: 8px;
  border-bottom: 1px solid #1e2533;
  margin-bottom: 1.75rem;
  flex-wrap: wrap;
}
.standard-product-layout .tab-nav-btn {
  padding: 10px 16px;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: #94a3b8;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
}
.standard-product-layout .tab-nav-btn.active {
  color: #ffffff;
  border-bottom-color: #ff5e3a;
}
.standard-product-layout .tab-pane {
  display: none;
}
.standard-product-layout .tab-pane.active {
  display: block;
}
.standard-product-layout .rich-desc-content {
  font-size: 1rem;
  line-height: 1.75;
  color: #cbd5e1;
}
.standard-product-layout .rich-desc-content h3,
.standard-product-layout .rich-desc-content h4 {
  color: #ffffff;
  margin: 1.25rem 0 0.6rem;
}
.standard-product-layout .rich-desc-content ul {
  padding-left: 1.25rem;
  margin: 0.75rem 0;
}
.standard-product-layout .rich-desc-content li {
  margin-bottom: 0.45rem;
}
.standard-product-layout .specs-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.standard-product-layout .specs-table th,
.standard-product-layout .specs-table td {
  padding: 12px 14px;
  border-bottom: 1px solid #1e2533;
  text-align: left;
}
.standard-product-layout .specs-table th {
  color: #94a3b8;
  font-weight: 700;
  width: 220px;
}
.standard-product-layout .specs-table td {
  color: #e5e7eb;
}
.standard-product-layout .product-tags-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid #1e2533;
}
.standard-product-layout .tag-pill {
  padding: 4px 10px;
  border-radius: 6px;
  background: #161b26;
  border: 1px solid #232b3a;
  color: #cbd5e1;
  font-size: 0.78rem;
}
.standard-product-layout .related-products-section {
  padding: 3.5rem 0 4.5rem;
}
.standard-product-layout .related-header {
  text-align: center;
  margin-bottom: 2rem;
}
.standard-product-layout .related-tag {
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #ff5e3a;
}
.standard-product-layout .related-heading {
  font-family: 'Montserrat', sans-serif;
  font-size: 1.75rem;
  font-weight: 800;
  color: #ffffff;
  margin: 6px 0 0;
}
.standard-product-layout .related-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
}
.standard-product-layout .related-card {
  background: #11141c;
  border: 1px solid #1e2533;
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.standard-product-layout .related-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255, 94, 58, 0.45);
}
.standard-product-layout .related-thumb-link {
  position: relative;
  display: block;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  background: #0d1018;
}
.standard-product-layout .related-thumb-link img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.standard-product-layout .related-cat-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 3px 9px;
  border-radius: 9999px;
  background: rgba(9, 10, 15, 0.8);
  color: #ff7b5a;
  font-size: 0.7rem;
  font-weight: 700;
}
.standard-product-layout .related-body {
  padding: 16px;
}
.standard-product-layout .related-title {
  font-size: 1rem;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 8px 0;
}
.standard-product-layout .related-title a {
  color: inherit;
  text-decoration: none;
}
.standard-product-layout .related-price-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.standard-product-layout .rel-price {
  font-weight: 800;
  color: #ffffff;
}
.standard-product-layout .rel-compare {
  color: #64748b;
  text-decoration: line-through;
  font-size: 0.85rem;
}

/* Minimal Editorial Product Layout */
.editorial-product-layout {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: #090a0f;
  color: #f3f4f6;
  padding-bottom: 4rem;
}
.editorial-product-layout .layout-container {
  max-width: 980px;
  margin: 0 auto;
  padding: 0 20px;
}
.editorial-product-layout .editorial-header {
  text-align: center;
  padding: 2.5rem 0 1.75rem;
}
.editorial-product-layout .single-product-title {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  margin: 0.75rem 0 0.5rem;
  color: #ffffff;
}
.editorial-product-layout .single-product-subtitle {
  color: #94a3b8;
  font-size: 1.05rem;
  margin: 0 0 1rem;
}
.editorial-product-layout .editorial-hero-media {
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid #1e2533;
  margin-bottom: 2rem;
  background: #11141c;
}
.editorial-product-layout .editorial-hero-media img {
  width: 100%;
  max-height: 540px;
  object-fit: cover;
  display: block;
}
.editorial-product-layout .editorial-purchase-bar {
  background: #11141c;
  border: 1px solid #232b3a;
  border-radius: 16px;
  padding: 1.75rem;
  margin-bottom: 2.5rem;
}
.editorial-product-layout .product-category-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 9999px;
  background: rgba(255, 94, 58, 0.14);
  color: #ff7b5a;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  text-decoration: none;
}
.editorial-product-layout .main-price {
  font-size: 1.85rem;
  font-weight: 800;
  color: #fff;
}
.editorial-product-layout .strike-price {
  color: #64748b;
  text-decoration: line-through;
  margin-left: 8px;
}
.editorial-product-layout .btn-primary-buy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 20px;
  border-radius: 10px;
  background: #ff5e3a;
  color: #fff;
  font-weight: 700;
  text-decoration: none;
}
.editorial-product-layout .rich-desc-content {
  font-size: 1.04rem;
  line-height: 1.8;
  color: #cbd5e1;
}
